\emph{Let $u_1,\  u_2,\  u_3$ be solutions to (\ref{mineq1}) over disjoint
simply connected domains $D_1,\ D_2,\ D_3$ respectively.  Then for sufficiently large r,there exist
positive constants $\kappa_1$ and $\kappa_2$ such that }
\begin{equation}
\label{max}
\kappa_1 r<M(r,u_j)<\kappa_2 r\qquad (j=1,2,3).
\end{equation}

\emph{Let $u$ represent one of the solutions in Theorem 1 and parametrized
in $H$ as above.  For any $\alpha <\pi/2$, let $D_\alpha$ denote the image of $S_\alpha$.
Then in $D_\alpha$, the laplacian of $u$ tends to zero as
\begin{equation}
\label{laplacian}
|\Delta u(z)<K/|z| 
\end{equation}
for some $K=K(u,\alpha)$ and $|z|$ sufficiently large }.

\emph{ With the above notations, if for some $C>0$,
\begin{equation}
\label{initial1}
u(r_mz)/(r_mz)\leq C\quad r_m'\leq |r_mz|\leq r_m''\quad r_mz\in D,
\end{equation}
and
 $M_n=\underset{S(r_n'))}{\max}(|z|/r_n|, r_nu(z/r_n) )$
then
\begin{equation}
\label{4.2a}
 \text{\rm mod}_F\Gamma (r_n',r_n'') \leq \frac\pi{2(\log r_n'')^2}\left(\underset{D(r_n',r_n'')}
\iint  \frac{dx_1dx_2}{|z|^2}
)+2\pi^2 +o(1)\right)\ (m\to\infty).
\end{equation}
With the stronger condition
\begin{equation}
\label{initial 1a}
u(r_mz)/(r_mz)\to 0\quad r_m'\leq |r_mz|\leq r_m''\quad r_mz\in D,
\end{equation}
then
\begin{equation}
\label{4.2aa}
\text{\rm mod}_F\Gamma (r_n',r_n'') \leq \frac 1{(\log r_n'')^2}\left(\underset{D(r_n',r_n'')}
\iint  \frac{dx_1dx_2}{|z|^2}
)+2\pi^2 +o(1)\right)\ (m\to\infty).
\end{equation}}

\emph { Let $u$ satisfy (\ref{mineq1}) and
assume that for sequences
$ \{r_n'\}$ and  $\{r_n''\}$ satisfying $r_n''/r_n'\to\infty$, and that  (\ref{ugrowth}) holds for
$r_n'<|z|<r_n''$.  Then,}
\begin{equation}
\label{i}
\underset{n\to\infty}{\liminf}\frac 1 {\log r_n''}(1+o(1))\iint_{D(r_n',r_n'')}\frac{drd\theta}{r}\geq 2,
\end{equation}

\emph{With the above notations,  
let $R$
be a rectangle in the $\mu +i\nu$ plane
$$
R=\Sigma_\varepsilon\cap\ \{p \leq \mu\leq q\}\quad 0<p<q,
$$
and suppose that  $w(z)$ has dilatation less than $\delta_0$ in $w^{-1}(R)$. 
Then for $x_1+iy_1$ and $x_2+iy_2$ in $w^{-1}(R)$ ($x_1<x_2$) and $a=\pi-\varepsilon$, if
\begin{equation}
\label{Ahlfors1}
 \int_{x_1}^{x_2} \frac{dx}{\Theta(x)}>2\frac{1+\delta_0}{1-\delta_0}, 
\end{equation}
}
then
\begin{equation}
\label{Ahlfors4}
\mu_1(x_2)-\mu_2(x_1)\geq a\frac{(1-\delta_0)}{(1+\delta_0)}\int_{x_1}^{x_2}\frac{dx}{\Theta(x)} 
-4a.
\end{equation}

\emph{There exists a constant $K$ depending on $u$ such that, if $u$ is as in
(\ref{mineq1}), and $C>0$, then the curvature $\kappa=\kappa (C)$ 
of the level set $u=C$ satisfies  the 
inequaltiy} 
\begin{equation}
\label{curvature1} |\kappa|\leq \frac KC.
\end{equation}
